from lib import *

TEMPLATES = []
add = TEMPLATES.append


def re_state_var(help=None):
    return V("state", "State where the property is located", "select", True, "", STATE_CODES,
             help or "Two-letter code. Massless shows the notes for this state from the state reference (states.json): official forms, required disclosures, closing practice, notarization and recording, executory-contract and wholesaling rules.")


STATE_HOOK = S("State-specific requirements", """
The property is in {{state}}. The parties will comply with that state's requirements for this transaction, including required seller disclosures and forms, licensing rules, closing and recording requirements, and any mandatory statutory notices. Massless shows a summary of known requirements for {{state}} with this template. That summary is a starting point, may be incomplete or out of date, and is not part of this agreement. Any addendum or disclosure form the state requires will be attached and signed by the parties.""")

TX_LICENSEE = when("Texas notes", """
**Texas.** If a Texas real estate license holder negotiates this transaction, TREC rules generally require the license holder to use the TREC promulgated contract forms instead of this template. For most residential property with one dwelling unit, the seller must give the buyer the Seller's Disclosure Notice described in Texas Property Code §5.008 (or a substantially similar notice). If any recorded lien will stay on the property after the sale (for example a subject-to or wraparound transaction), Texas Property Code §5.016 requires the seller to give the buyer, and each lienholder, a separate written notice at least seven days before the contract is signed or the property is conveyed, whichever is earlier, unless an exception applies.""", "state == 'TX'")

CO_LICENSEE = when("Colorado notes", """
**Colorado.** Colorado brokers must use Colorado Real Estate Commission-approved forms when an approved form exists and is appropriate. The Commission publishes a Contract to Buy and Sell Real Estate (Residential) and a Seller's Property Disclosure (Residential) form.""", "state == 'CO'")

RE_SOURCES_BASE = [SRC["nar_disc"], SRC["trec"], SRC["crec"], SRC["lead_cfr"], SRC["lead_epa"], SRC["firpta"], SRC["esign_exc"]]

WIRE = "**Wire fraud warning.** Criminals send fake wiring instructions by email that look like they come from title companies, attorneys and agents. Before wiring any money, call the recipient at a phone number you get independently, not from the email, and confirm the instructions. Never trust a last-minute change to wiring instructions."

# ------------------------------------------------------------------ Residential purchase agreement
add(T(
    id="residential-purchase-agreement", title="Residential Purchase Agreement", category="real-estate",
    tags=["real estate", "purchase", "home sale", "fsbo", "contract", "state-aware"],
    summary="A plain-English contract to buy and sell a home, with financing, inspection, title and closing terms, plus hooks for state addenda.",
    useWhen="A buyer and seller are dealing directly (for example a for-sale-by-owner or investor purchase) and no licensee is required to use a state form. Pick the property's state so the state notes and addenda apply.",
    watchOuts=[
        "If a real estate licensee is involved, check whether the state requires its own form. Texas (TREC) and Colorado (Commission-approved forms) require licensees to use state forms, and Utah and Wisconsin also have state-approved forms. In other states, agents usually use copyrighted association forms.",
        "Required seller disclosures vary widely. Some states have a mandatory form (for example California, Texas, New York and Ohio). Others, such as Alabama, Arkansas and Georgia, have no general disclosure statute but still prohibit fraud and concealment. Federal law separately requires the lead-based paint disclosure for most homes built before 1978.",
        "Attorney states: in several states, for example Georgia, Massachusetts, South Carolina and Connecticut, closings are conducted or supervised by attorneys. Sources differ on the exact list, so verify locally.",
        "Deadlines run from the effective date. Count days carefully and put the effective date in writing.",
        "All owners on title must sign. In some states a non-owner spouse must also sign to release homestead or marital rights.",
        "If the seller is a foreign person, the buyer may have to withhold tax under FIRPTA (generally 15% of the amount realized) unless an exemption applies.",
        "Never wire earnest money or closing funds without confirming the instructions by phone with a known number. Real estate wire fraud is common.",
    ],
    stateAware=True, disclaimer=RE_DISCLAIMER,
    roles=[("buyer", "Buyer"), ("seller", "Seller")],
    variables=[
        re_state_var(),
        V("effective_date", "Effective date", "date", help="Date the last party signs. Deadlines are counted from this date."),
        V("buyer_name", "Buyer name(s)", "party", help="Everyone who will take title."),
        V("buyer_address", "Buyer address", "address", help="For notices."),
        V("buyer_email", "Buyer email", "email", help="For notices."),
        V("seller_name", "Seller name(s)", "party", help="Everyone on title."),
        V("seller_address", "Seller address", "address", help="For notices."),
        V("seller_email", "Seller email", "email", help="For notices."),
        V("property_address", "Property address", "address", help="Street address, city, ZIP."),
        V("county", "County", "text", help="County where recorded."),
        V("legal_description", "Legal description", "longtext", help="From the deed or title commitment, e.g. 'Lot 4, Block 2, Oak Hills Subdivision...'."),
        V("parcel_number", "Parcel or tax ID number", "text", False, help="Assessor's parcel number."),
        V("included_items", "Included items", "longtext", False, "All fixtures and attached items, including window coverings, ceiling fans, built-in appliances, and the following: ", help="Personal property included in the sale."),
        V("excluded_items", "Excluded items", "longtext", False, "None", help="Items the seller keeps."),
        V("price", "Purchase price", "money", help="Total price."),
        V("earnest_money", "Earnest money", "money", help="Deposit showing good faith."),
        V("escrow_holder", "Earnest money held by", "text", help="Title company, escrow agent or closing attorney (name and address)."),
        V("earnest_days", "Days to deliver earnest money", "number", default="3", help="Business days after the effective date."),
        V("financing", "How the buyer pays", "select", default="new loan", options=["cash", "new loan", "seller financing", "subject to existing financing"], help="Seller financing and subject-to require the matching addendum."),
        V("loan_amount", "Loan amount", "money", False, help="Amount of the buyer's new loan."),
        V("loan_type", "Loan type", "select", False, "conventional", ["conventional", "FHA", "VA", "USDA", "other"], help="FHA and VA loans have required addenda and appraisal rules."),
        V("loan_days", "Days to obtain loan approval", "number", False, "30", help="Financing contingency deadline."),
        V("proof_days", "Days to provide proof of funds", "number", False, "3", help="For cash purchases."),
        V("appraisal", "Include an appraisal contingency?", "bool", False, "true", help="If the property appraises below the price, the buyer may renegotiate or terminate."),
        V("inspection_days", "Inspection period (days)", "number", default="10", help="Days to inspect and terminate."),
        V("inspection_basis", "Buyer may terminate during inspection period", "select", default="for any reason", options=["for any reason", "only for material defects found by inspection"], help="'For any reason' protects the buyer most."),
        V("as_is", "Sold as is?", "bool", False, "false", help="The seller makes no repairs, but disclosure duties still apply."),
        V("built_before_1978", "Built before 1978?", "bool", False, "false", help="Triggers the federal lead-based paint disclosure and 10-day inspection opportunity."),
        V("hoa", "In a homeowners or condo association?", "bool", False, "false", help="Adds association document review."),
        V("hoa_review_days", "Days to review association documents", "number", False, "5", help="After receiving them."),
        V("deed_type", "Type of deed", "select", default="general warranty deed", options=["general warranty deed", "special warranty deed", "grant deed", "bargain and sale deed", "quitclaim deed"], help="Check what is customary in your state. A quitclaim gives the buyer the least protection."),
        V("title_days", "Days to deliver title commitment", "number", default="15", help="Seller or title company delivers the commitment."),
        V("objection_days", "Days for buyer's title objections", "number", default="5", help="After receiving the commitment."),
        V("survey", "Buyer will obtain a survey?", "bool", False, "false", help="New survey at buyer's cost."),
        V("closing_date", "Closing date", "date", help="On or before this date."),
        V("closing_agent", "Closing agent", "text", help="Title company or closing attorney who will close."),
        V("closing_costs", "Closing costs", "select", default="as customary in the county where the property is located", options=["as customary in the county where the property is located", "as listed in Additional terms"], help="Who pays which costs."),
        V("seller_credit", "Seller credit to buyer", "money", False, "0", help="Credit toward buyer's closing costs, if any."),
        V("possession", "Possession", "select", default="at closing", options=["at closing", "after closing (seller rent-back)"], help="When the buyer gets the keys."),
        V("rentback_days", "Seller rent-back days", "number", False, help="Days the seller may stay after closing."),
        V("rentback_rate", "Rent-back rate per day", "money", False, help="Daily amount."),
        V("default_remedy", "If the buyer defaults, the seller's remedy is", "select", default="keep the earnest money as liquidated damages", options=["keep the earnest money as liquidated damages", "any remedy allowed by law"], help="Liquidated damages limit the buyer's exposure."),
        V("attorney_review", "Include an attorney review period?", "bool", False, "false", help="Common in some states, for example New Jersey and Illinois. Either party's attorney may disapprove within the period."),
        V("attorney_review_days", "Attorney review period (business days)", "number", False, "3", help="Length."),
        V("brokers", "Is any broker or agent involved?", "bool", False, "false", help="Names and how they are paid."),
        V("broker_details", "Brokers and compensation", "longtext", False, help="Each broker, whom they represent, and the compensation agreement."),
        V("addenda", "Attached addenda", "longtext", False, "None", help="List every addendum and disclosure attached."),
        V("additional_terms", "Additional terms", "longtext", False, "None", help="Anything else agreed."),
        V("offer_expires", "Offer expires", "text", help="Date and time this offer expires if not accepted."),
    ],
    sections=[
        S("Parties", "**Buyer:** {{buyer_name}}, {{buyer_address}} ({{buyer_email}})\n\n**Seller:** {{seller_name}}, {{seller_address}} ({{seller_email}})\n\nSeller agrees to sell and Buyer agrees to buy the Property on these terms. This agreement takes effect on {{effective_date}} (the \"Effective Date\")."),
        S("Property", "The real property at {{property_address}}, {{county}} County, {{state}}, legally described as:\n\n{{legal_description}}\n\nParcel number: {{parcel_number}}. The sale includes all improvements, fixtures and these items: {{included_items}}\n\nExcluded: {{excluded_items}}"),
        S("Price", "The purchase price is {{price}}, paid as follows: earnest money of {{earnest_money}}, which is credited to Buyer at closing, the financing described below, and the balance in good funds at closing. Seller will credit Buyer {{seller_credit}} at closing toward Buyer's closing costs, prepaid items and other allowed costs, if a credit is stated and the lender allows it."),
        S("Earnest money", "Buyer will deliver the earnest money to {{escrow_holder}} within {{earnest_days}} business days after the Effective Date. It is released only under this agreement, under joint written instructions, or by court order. If Buyer terminates under a right in this agreement, the earnest money is refunded to Buyer.\n\n" + WIRE),
        when("Financing: cash", "This is a cash purchase, with no financing contingency. Within {{proof_days}} days after the Effective Date, Buyer will provide reasonable written proof of funds, such as a bank or brokerage statement. If Buyer does not, Seller may terminate by written notice until the proof is delivered.", "financing == 'cash'"),
        when("Financing: new loan", "Buyer's obligation is contingent on Buyer obtaining a {{loan_type}} loan of {{loan_amount}} on terms acceptable to Buyer. Buyer will apply within 5 days after the Effective Date and make good-faith efforts to obtain approval. If Buyer cannot obtain loan approval within {{loan_days}} days after the Effective Date, Buyer may terminate by written notice before that deadline and receive the earnest money. If Buyer does not give notice, this contingency is waived. Any FHA, VA or other lender-required addenda are attached.", "financing == 'new loan'"),
        when("Financing: seller financing", "Seller will finance part of the price on the terms in the attached Seller Financing Addendum. The note will be secured by a mortgage or deed of trust on the Property, recorded at closing. The parties acknowledge that federal and state lending laws may apply to seller financing.", "financing == 'seller financing'"),
        when("Financing: subject to existing financing", "Buyer will take title subject to Seller's existing loan(s) on the terms in the attached Subject-To Addendum and Seller Acknowledgments and Disclosures. **The existing loan stays in Seller's name, and the lender may have the right to call the loan due when title transfers.** Seller: [[initial:seller]] Buyer: [[initial:buyer]]", "financing == 'subject to existing financing'"),
        opt("Appraisal", "If the Property appraises for less than the purchase price, Buyer may, within 5 days after receiving the appraisal, (a) proceed at the contract price, (b) propose a revised price, or (c) terminate and receive the earnest money. If the parties do not agree to a revised price within 3 days after Buyer's proposal, either party may terminate and the earnest money is refunded to Buyer.", "appraisal"),
        S("Title and survey", "Seller will convey marketable title by {{deed_type}}, free of liens except those Buyer agrees to in writing, and subject only to recorded easements, restrictions and other matters that do not materially interfere with residential use. Within {{title_days}} days after the Effective Date, Seller will cause the closing agent to deliver a title commitment, with copies of exception documents. Buyer has {{objection_days}} days after receiving them to object in writing. Seller may cure objections before closing. If Seller does not or cannot, Buyer may waive them or terminate and receive the earnest money. Seller will pay off at or before closing all monetary liens not assumed by Buyer."),
        opt("Survey", "Buyer will obtain a survey at Buyer's expense before the title objection deadline. Survey matters may be objected to as title objections.", "survey"),
        S("Seller disclosures", "Within 5 days after the Effective Date (or earlier if the law requires), Seller will deliver all disclosures required by the law of {{state}} and by federal law. Seller will disclose known material defects that are not readily observable, as the law requires. These disclosures are not warranties, and they do not replace Buyer's own inspections. If a required disclosure is delivered late, Buyer has any termination or other rights the law provides."),
        opt("Lead-based paint (homes built before 1978)", "The home was built before 1978. Before Buyer is obligated under this agreement, Seller will complete and both parties will sign the federal Lead-Based Paint Disclosure (40 CFR 745.113), and Seller will give Buyer the EPA pamphlet \"Protect Your Family From Lead in Your Home.\" Buyer has 10 days after the Effective Date (or another period the parties agree in writing) to conduct a lead-based paint inspection or risk assessment at Buyer's expense, unless Buyer waives this right in the disclosure. If the inspection shows lead-based paint hazards, Buyer may terminate within that period and receive the earnest money.", "built_before_1978"),
        opt("Homeowners or condominium association", "The Property is in an owners' association. Seller will deliver, or cause the association to deliver, the governing documents, budget, current assessments, any special assessments and resale certificate required by law. Buyer may terminate within {{hoa_review_days}} days after receiving them and receive the earnest money. Transfer fees are paid as customary, unless otherwise agreed.", "hoa"),
        S("Inspections", "Buyer and its inspectors may inspect the Property, including structural, mechanical, roof, pest, sewer and environmental conditions, during the {{inspection_days}}-day period after the Effective Date (the \"Inspection Period\"). Seller will provide reasonable access with utilities on. Buyer will repair any damage the inspections cause and keep the Property free of liens from them. During the Inspection Period Buyer may terminate {{inspection_basis}} by written notice and receive the earnest money, or ask Seller to make repairs. If Buyer does not terminate in time, Buyer accepts the Property's condition, subject to the rest of this agreement."),
        opt("Sold as is", "Seller will not make repairs. Buyer accepts the Property in its present \"as is\" condition, subject to Buyer's inspection rights, Seller's disclosure obligations under the law, and Seller's duty to keep the Property in its present condition until closing. \"As is\" does not excuse fraud or the concealment of known defects. Buyer: [[initial:buyer]] Seller: [[initial:seller]]", "as_is"),
        S("Condition until closing", "Seller will maintain the Property in its present condition, normal wear excepted, keep utilities on, and not make changes to the Property or enter new leases or agreements affecting it without Buyer's written consent. Buyer may do a walk-through within 48 hours before closing."),
        S("Closing", "Closing will take place on or before {{closing_date}} through {{closing_agent}}, or as the parties agree in writing. Seller will deliver the signed deed and documents customary in {{state}}, including a certificate of non-foreign status or other FIRPTA documentation. Buyer will deliver the balance of the price and loan documents. Closing costs are paid {{closing_costs}}. Property taxes, association dues, rents and utilities are prorated to the closing date. The deed and any security instruments will be notarized and recorded as required by law."),
        when("Possession: at closing", "Seller will deliver possession, keys and access codes at closing, with the Property vacant and broom-clean, and free of debris and personal property not included in the sale.", "possession == 'at closing'"),
        when("Possession: seller rent-back", "Seller may remain in possession for {{rentback_days}} days after closing, paying Buyer {{rentback_rate}} per day, credited at closing. Seller will maintain the Property and insurance on its belongings, and deliver possession vacant and broom-clean at the end. The parties will sign a separate short-term occupancy agreement.", "possession == 'after closing (seller rent-back)'"),
        S("Risk of loss", "Seller bears the risk of loss until closing. If the Property is materially damaged before closing, Buyer may terminate and receive the earnest money, or close and receive any insurance proceeds for the damage plus a credit for the deductible."),
        S("Default", "If Seller fails to perform, Buyer may seek specific performance, or terminate and receive the earnest money and pursue other remedies allowed by law. If Buyer fails to perform without a valid right to terminate, Seller's remedy is to {{default_remedy}}. Before declaring a default, the non-defaulting party will give written notice and 3 business days to cure, except for failure to close on the closing date."),
        opt("Attorney review", "Either party's attorney may review this agreement and disapprove it, or propose changes, by written notice delivered within {{attorney_review_days}} business days after the Effective Date. If disapproved and the parties do not agree to changes, this agreement ends and the earnest money is refunded to Buyer.", "attorney_review"),
        opt("Brokers", "{{broker_details}}\n\nEach party confirms it has not dealt with any other broker, and will indemnify the other against claims for compensation by brokers it engaged.", "brokers"),
        STATE_HOOK, TX_LICENSEE, CO_LICENSEE,
        S("Addenda and additional terms", "Attached addenda: {{addenda}}\n\nAdditional terms: {{additional_terms}}"),
        S("General", "Time is of the essence. Deadlines that fall on a weekend or legal holiday move to the next business day. This agreement binds the parties' heirs and successors. Buyer may not assign it without Seller's written consent, unless an addendum says otherwise. The law of {{state}} governs. This agreement is the entire agreement and can be changed only in a signed writing. It may be signed in counterparts and electronically. Electronic signatures do not replace any notarization or recording the law requires for the deed. Notices go to the addresses and emails above."),
        S("Offer and acceptance", "This document is Buyer's offer. It expires if Seller has not signed it and delivered it to Buyer by {{offer_expires}}."),
        signatures([("buyer", "Buyer", "{{buyer_name}}"), ("seller", "Seller", "{{seller_name}}")]),
    ],
    sources=RE_SOURCES_BASE + [SRC["tx_5016"], src("Tex. Prop. Code §5.008 seller's disclosure notice", "https://texas.public.law/statutes/tex._prop._code_section_5.008"), src("FBI IC3 public service announcement: Business email compromise (Sept. 2024)", "https://www.ic3.gov/PSA/2024/PSA240911"), SRC["homelight_attorney"], SRC["lodestar_attorney"]],
))

# ------------------------------------------------------------------ LOI
add(T(
    id="real-estate-loi", title="Real Estate Letter of Intent (Non-Binding)", category="real-estate",
    tags=["loi", "letter of intent", "offer", "commercial", "investor"],
    summary="Outline the key deal terms for a property before negotiating a full purchase contract. Mostly non-binding.",
    useWhen="Making an offer on investment, commercial or multifamily property where a detailed purchase agreement will follow.",
    watchOuts=[
        "Courts sometimes enforce LOIs as contracts when they look complete and the parties act on them. Keep the non-binding language clear, and keep binding terms short.",
        "Exclusivity ('no-shop') and confidentiality are usually the only binding terms. Keep exclusivity short.",
        "An LOI is not a substitute for a purchase agreement or state-required disclosures.",
    ],
    disclaimer=RE_DISCLAIMER,
    roles=[("buyer", "Prospective buyer"), ("seller", "Property owner")],
    variables=[
        V("loi_date", "Date", "date", help="Date of the letter."),
        V("buyer_name", "Buyer name", "party", help="Buyer or buying entity, 'and/or assigns' if applicable."),
        V("seller_name", "Owner name", "party", help="Current owner."),
        V("property_address", "Property", "address", help="Address and short description."),
        V("price", "Proposed price", "money", help="Offer price."),
        V("terms", "Payment terms", "longtext", default="All cash at closing.", help="Cash, new loan, seller financing, subject-to, or a combination."),
        V("earnest_money", "Earnest money", "money", help="Deposit with the purchase agreement."),
        V("due_diligence_days", "Due diligence period (days)", "number", default="30", help="After the purchase agreement is signed."),
        V("diligence_items", "Documents the seller will provide", "longtext", False, "Rent roll, leases, trailing 12 months of operating statements, utility bills, tax bills, service contracts, existing surveys and environmental reports.", help="What the buyer needs to review."),
        V("closing_days", "Close within (days after due diligence)", "number", default="30", help="Timeline."),
        V("contingencies", "Contingencies", "longtext", False, "Satisfactory due diligence, financing on terms acceptable to buyer, clear title.", help="Main conditions."),
        V("exclusivity", "Seller agrees to exclusivity?", "bool", False, "false", help="Seller stops marketing for a short period."),
        V("exclusivity_days", "Exclusivity period (days)", "number", False, "30", help="Keep it short."),
        V("expires", "LOI expires", "date", help="Date the seller must sign by."),
        state_var("governing_state", "State whose law applies", help="Usually the property's state."),
    ],
    sections=[
        S("Purpose", "Date: {{loi_date}}. This letter summarizes the main terms on which {{buyer_name}} (\"Buyer\") proposes to buy {{property_address}} (the \"Property\") from {{seller_name}} (\"Seller\"). The parties intend to negotiate a definitive purchase agreement."),
        S("Proposed terms", "- **Price:** {{price}}\n- **Payment:** {{terms}}\n- **Earnest money:** {{earnest_money}}, deposited with a title company or closing attorney when the purchase agreement is signed\n- **Due diligence:** {{due_diligence_days}} days after the purchase agreement is signed, during which Buyer may terminate for any reason\n- **Seller documents:** {{diligence_items}}\n- **Closing:** within {{closing_days}} days after due diligence ends\n- **Contingencies:** {{contingencies}}"),
        S("Not binding", "**Except for the sections titled Confidentiality, Exclusivity (if included), Costs and Governing law, this letter is not a binding contract.** It creates no obligation to buy or sell, and no obligation to negotiate further. Either party may stop negotiations at any time for any reason. A binding agreement exists only when both parties sign a definitive purchase agreement."),
        S("Confidentiality", "Each party will keep the terms of this letter and any non-public information it receives about the Property confidential, except for disclosure to its advisers, lenders and investors who need to know."),
        opt("Exclusivity", "For {{exclusivity_days}} days after Seller signs, Seller will not market the Property, solicit offers or negotiate with anyone else about a sale.", "exclusivity"),
        S("Costs", "Each party pays its own costs of negotiating this letter and the purchase agreement."),
        S("Governing law and expiration", "The binding sections are governed by the law of {{governing_state}}. This letter expires if not signed by Seller by {{expires}}."),
        signatures([("buyer", "Prospective buyer", "{{buyer_name}}", True), ("seller", "Property owner", "{{seller_name}}", True)], "Acknowledged and agreed, including the binding sections:"),
    ],
    sources=[src("Pryor Cashman: The enforceability of letters of intent", "https://www.pryorcashman.com/publications/the-enforceability-of-letters-of-intent"), SRC["esign"]],
))

# ------------------------------------------------------------------ Assignment of contract
add(T(
    id="assignment-of-contract", title="Assignment of Real Estate Purchase Contract", category="real-estate",
    tags=["assignment", "wholesale", "assignment fee", "investor", "state-aware"],
    summary="Transfer a buyer's rights under a purchase contract to a new buyer for an assignment fee, with the disclosures many states now require.",
    useWhen="A buyer under contract (the assignor) transfers the contract to another buyer (the assignee) who will close with the seller.",
    watchOuts=[
        "Many states now regulate wholesaling, including Illinois, Oklahoma, Pennsylvania, Ohio, Oregon, Texas, Virginia, Connecticut, Maryland, Tennessee, Wisconsin, Iowa and others. Rules include licensing after a number of deals, written disclosure to the seller and buyer that you hold only an equitable interest, seller cancellation rights and registration. Check the state notes and verify locally before marketing or assigning.",
        "Marketing the property itself, rather than the contract, before you own it can be unlicensed brokerage in many states.",
        "Check that the purchase contract allows assignment. Many contracts and all FHA/VA-related and REO contracts prohibit it or require seller consent.",
        "Assignment fees are often visible to the seller on the closing statement. Some states now require the fee, or its existence, to be disclosed.",
        "The assignor usually remains liable under the original contract unless the seller releases the assignor (a novation).",
    ],
    stateAware=True, disclaimer=RE_DISCLAIMER,
    roles=[("assignor", "Assignor (original buyer)"), ("assignee", "Assignee (new buyer)")],
    variables=[
        re_state_var(),
        V("assignment_date", "Date", "date", help="Date of the assignment."),
        V("assignor_name", "Assignor name", "party", help="Buyer named in the purchase contract."),
        V("assignor_email", "Assignor email", "email", help="For notices."),
        V("assignee_name", "Assignee name", "party", help="New buyer."),
        V("assignee_email", "Assignee email", "email", help="For notices."),
        V("seller_name", "Seller name", "text", help="Seller under the purchase contract."),
        V("contract_date", "Purchase contract date", "date", help="Effective date of the original contract."),
        V("property_address", "Property address", "address", help="Property under contract."),
        V("contract_price", "Contract purchase price", "money", help="Price the assignee will pay the seller at closing."),
        V("assignment_fee", "Assignment fee", "money", help="Amount the assignee pays the assignor."),
        V("fee_deposit", "Assignee's deposit toward the fee", "money", False, "0", help="Paid at signing to the closing agent."),
        V("deposit_refundable", "Is the assignee's deposit refundable?", "select", default="refundable only if the seller fails to close", options=["refundable only if the seller fails to close", "refundable for any reason until the inspection deadline", "non-refundable"], help="When the deposit comes back."),
        V("earnest_reimbursed", "Reimburse assignor's earnest money at closing?", "bool", False, "true", help="Assignee reimburses the earnest money the assignor deposited, or replaces it."),
        V("assignor_earnest", "Assignor's earnest money amount", "money", False, help="Amount deposited under the purchase contract."),
        V("closing_agent", "Closing agent", "text", help="Title company or attorney closing the sale."),
        V("closing_date", "Closing date", "date", help="From the purchase contract."),
        V("consent_status", "Seller consent", "select", default="the purchase contract allows assignment without consent", options=["the purchase contract allows assignment without consent", "written seller consent is attached", "seller consent will be obtained before closing"], help="Check the contract's assignment clause."),
        V("disclosure_given", "Seller received a wholesaler or equitable-interest disclosure?", "select", default="yes, a written disclosure was given before the contract", options=["yes, a written disclosure was given before the contract", "not required in this state (verify locally)"], help="Several states require written disclosure to the seller and to buyers."),
    ],
    sections=[
        S("Parties", "**Assignor:** {{assignor_name}} ({{assignor_email}})\n\n**Assignee:** {{assignee_name}} ({{assignee_email}})"),
        S("Contract assigned", "Assignor is the buyer under a purchase contract with {{seller_name}} (\"Seller\") dated {{contract_date}} for the property at {{property_address}} in {{state}} (the \"Purchase Contract\"), at a price of {{contract_price}}. A copy of the Purchase Contract and its amendments has been given to Assignee. Assignee initials to confirm receipt: [[initial:assignee]]"),
        S("Assignment", "Effective on {{assignment_date}}, Assignor assigns to Assignee all of Assignor's rights under the Purchase Contract, and Assignee accepts the assignment and assumes all of the buyer's obligations under it from that date, including closing on or before {{closing_date}} and paying the purchase price."),
        S("Assignment fee", "Assignee will pay Assignor an assignment fee of {{assignment_fee}}, payable through {{closing_agent}} at closing. Assignee deposits {{fee_deposit}} toward the fee with the closing agent on signing. This deposit is {{deposit_refundable}}. If the sale does not close because Seller defaults, or because of a contingency in the Purchase Contract that Assignee properly exercises, the deposit is returned to Assignee, unless it is non-refundable."),
        opt("Earnest money", "At closing, Assignee will reimburse Assignor for the {{assignor_earnest}} earnest money that Assignor deposited under the Purchase Contract, or Assignee will deposit replacement earnest money so Assignor's deposit is returned.", "earnest_reimbursed"),
        S("Seller consent", "Status: {{consent_status}}. If consent is required and not obtained before closing, either party may cancel this assignment and Assignee's deposit is returned."),
        S("Nature of assignor's interest", "Assignee understands that Assignor (a) does not own the property, (b) holds only an equitable interest as the buyer under the Purchase Contract, (c) is not acting as Assignee's real estate agent or broker, and (d) is profiting from this assignment through the assignment fee. Assignor may not be able to deliver title. Title will come from Seller at closing. Assignee: [[initial:assignee]]"),
        S("Disclosure to seller", "Assignor states that: {{disclosure_given}}. Assignor is responsible for complying with any wholesaling, licensing, disclosure or registration law of {{state}} that applies to Assignor."),
        S("Assignor's promises", "Assignor promises that (a) the Purchase Contract is in effect and has not been amended except as disclosed, (b) Assignor has not previously assigned it, (c) Assignor has not received notice of any default, and (d) Assignor will not amend or terminate the Purchase Contract without Assignee's consent."),
        S("Assignee's independent evaluation", "Assignee has relied on its own inspection, valuation and due diligence, not on statements by Assignor. Assignor makes no promise about the property's value, condition, rents, repair costs or after-repair value."),
        S("Liability", "Assignee will indemnify Assignor against claims arising from Assignee's failure to perform the buyer's obligations under the Purchase Contract after the assignment. Assignor remains liable to Seller unless Seller releases Assignor in writing."),
        STATE_HOOK,
        S("General", "This assignment is governed by the law of {{state}}. It is the entire agreement about the assignment. It may be signed electronically and in counterparts. The closing agent may rely on it to disburse the assignment fee."),
        signatures([("assignor", "Assignor", "{{assignor_name}}", True), ("assignee", "Assignee", "{{assignee_name}}", True)]),
    ],
    sources=[SRC["wholesale_tracker"], SRC["il_454"], SRC["tx_oc1101"], src("Oklahoma SB 1075 (2025) enrolled text", "https://www.oklegislature.gov/cf_pdf/2025-26%20ENR/SB/SB1075%20ENR.PDF"), src("Ohio Rev. Code §5301.95 (wholesaler disclosure)", "https://codes.ohio.gov/ohio-revised-code/section-5301.95"), src("Pennsylvania SB 1173 of 2023-24 (Act 52 of 2024)", "https://www.palegis.us/legislation/bills/2023/sb1173"), src("Oregon Real Estate Agency: residential property wholesaling", "https://www.oregon.gov/rea/pages/residential-property-wholesaling.aspx")],
))

# ------------------------------------------------------------------ Earnest money receipt
add(T(
    id="earnest-money-receipt", title="Earnest Money Receipt", category="real-estate",
    tags=["earnest money", "escrow", "deposit", "receipt"],
    summary="Acknowledge receipt of an earnest money deposit and state how it will be held and released.",
    useWhen="A title company, escrow agent, attorney or seller receives the buyer's deposit under a purchase contract.",
    watchOuts=[
        "Licensees and escrow agents must follow state trust-account rules for holding deposits, including deposit deadlines and separate accounts. Sellers holding deposits themselves is risky for buyers.",
        "If there is a dispute, most holders will not release the deposit without joint instructions or a court order. Some states have specific release procedures.",
        "Confirm wiring instructions by phone using a known number. Earnest money wires are a top target for fraud.",
    ],
    disclaimer=RE_DISCLAIMER,
    roles=[("holder", "Escrow holder"), ("buyer", "Buyer")],
    variables=[
        V("receipt_date", "Date received", "date", help="Date funds were received."),
        V("holder_name", "Escrow holder", "party", help="Title company, attorney, broker or seller holding the deposit."),
        V("holder_address", "Holder address", "address", help="Address."),
        V("buyer_name", "Buyer", "party", help="Who paid the deposit."),
        V("seller_name", "Seller", "text", help="Seller under the contract."),
        V("property_address", "Property", "address", help="Property address."),
        V("contract_date", "Purchase contract date", "date", help="Contract the deposit relates to."),
        V("amount", "Amount", "money", help="Deposit amount."),
        V("form", "Form of payment", "select", default="wire transfer", options=["wire transfer", "official bank check", "personal check", "ACH", "other"], help="How it was paid."),
        V("reference", "Check or reference number", "text", False, help="Check number or wire reference."),
        V("account_type", "Funds held in", "text", default="a federally insured escrow or trust account", help="Where the funds are held."),
        V("interest", "Interest-bearing account?", "bool", False, "false", help="If on, say who gets the interest."),
        V("interest_to", "Interest belongs to", "select", False, "Buyer", ["Buyer", "Seller", "the party who receives the deposit"], help="Who receives interest."),
    ],
    sections=[
        S("Receipt", "{{holder_name}}, {{holder_address}} (\"Holder\") acknowledges receiving {{amount}} from {{buyer_name}} (\"Buyer\") on {{receipt_date}} by {{form}} (reference {{reference}}), as earnest money under the purchase contract dated {{contract_date}} between Buyer and {{seller_name}} (\"Seller\") for {{property_address}}. Receipt of a check is subject to collection. If a check is dishonored, Holder will notify both parties promptly."),
        S("Holding the deposit", "Holder will keep the deposit in {{account_type}}, separate from Holder's own funds, as the law requires."),
        opt("Interest", "The account bears interest. Interest belongs to {{interest_to}}. Buyer will provide a Form W-9 if requested.", "interest"),
        S("Release", "Holder will release the deposit (a) at closing, as a credit to Buyer, (b) according to joint written instructions signed by Buyer and Seller, (c) as the purchase contract clearly provides after notice to both parties where the law allows, or (d) under a court order. If Buyer and Seller dispute who is entitled to the deposit, Holder may keep it until the dispute is resolved, or deposit it with a court and ask the court to decide (interpleader), as allowed by state law."),
        S("Holder's role", "Holder is a stakeholder only, does not represent either party, and is not liable for acting in good faith under this receipt. This receipt does not change the purchase contract."),
        S("Wire fraud", WIRE),
        signatures([("holder", "Escrow holder", "{{holder_name}}", True), ("buyer", "Buyer", "{{buyer_name}}")], "Signed by Holder, and acknowledged by Buyer:"),
    ],
    sources=[src("FBI IC3 public service announcement: Business email compromise (Sept. 2024)", "https://www.ic3.gov/PSA/2024/PSA240911"), src("CFPB: Mortgage closing scams", "https://www.consumerfinance.gov/about-us/blog/mortgage-closing-scams-how-protect-yourself-and-your-closing-funds/"), SRC["trec"]],
))

# ------------------------------------------------------------------ Amendment / addendum
add(T(
    id="real-estate-contract-amendment", title="Amendment to Real Estate Purchase Contract", category="real-estate",
    tags=["amendment", "addendum", "change", "closing date", "price", "repairs"],
    summary="Change the price, closing date, repairs or other terms of a signed purchase contract.",
    useWhen="Buyer and seller agree to change a signed purchase contract, for example after inspection, appraisal or a financing delay.",
    watchOuts=[
        "Lenders must approve price and credit changes. Concessions above the loan program's limits can be disallowed.",
        "Changing the closing date can affect rate locks, loan approval and the seller's next purchase.",
        "Repair agreements should say who does the work, to what standard, by when, and whether licensed contractors and receipts are required.",
        "If a licensee is involved, use the state-required amendment form where one exists.",
    ],
    disclaimer=RE_DISCLAIMER,
    roles=[("buyer", "Buyer"), ("seller", "Seller")],
    variables=[
        V("amendment_date", "Date", "date", help="Date of this amendment."),
        V("amendment_number", "Amendment number", "text", default="1", help="Sequential number."),
        V("buyer_name", "Buyer", "party", help="Buyer."),
        V("seller_name", "Seller", "party", help="Seller."),
        V("property_address", "Property", "address", help="Property address."),
        V("contract_date", "Original contract date", "date", help="Effective date of the contract."),
        V("change_price", "Change the price?", "bool", False, "false", help="New purchase price."),
        V("new_price", "New purchase price", "money", False, help="Revised price."),
        V("change_closing", "Change the closing date?", "bool", False, "false", help="New closing date."),
        V("new_closing", "New closing date", "date", False, help="Revised date."),
        V("repairs", "Seller repairs or credits?", "bool", False, "false", help="Agreed repairs or credits."),
        V("repair_terms", "Repairs or credits", "longtext", False, help="What, by whom, standard, deadline, receipts. Or the amount of the credit."),
        V("other_changes", "Other changes", "longtext", False, "None", help="Any other changes to the contract."),
    ],
    sections=[
        S("Contract amended", "Amendment no. {{amendment_number}}, dated {{amendment_date}}, to the purchase contract dated {{contract_date}} between {{buyer_name}} (\"Buyer\") and {{seller_name}} (\"Seller\") for {{property_address}} (the \"Contract\")."),
        opt("Price", "The purchase price is changed to {{new_price}}.", "change_price"),
        opt("Closing date", "The closing date is changed to {{new_closing}}. Other deadlines are not changed unless stated here.", "change_closing"),
        opt("Repairs and credits", "{{repair_terms}}\n\nRepairs will be completed in a workmanlike manner, by licensed contractors where the law requires, with permits where required, and receipts will be provided to Buyer before closing. Credits are subject to lender approval.", "repairs"),
        S("Other changes", "{{other_changes}}"),
        S("Everything else stays the same", "Except as changed by this amendment, the Contract remains in full effect. If this amendment and the Contract conflict, this amendment controls. Electronic signatures are valid."),
        signatures([("buyer", "Buyer", "{{buyer_name}}"), ("seller", "Seller", "{{seller_name}}")]),
    ],
    sources=[SRC["trec"], SRC["crec"], SRC["esign"]],
))

# ------------------------------------------------------------------ Termination
add(T(
    id="real-estate-contract-termination", title="Termination of Purchase Contract and Release of Earnest Money", category="real-estate",
    tags=["termination", "cancellation", "earnest money release", "mutual release"],
    summary="End a purchase contract by agreement and tell the escrow holder how to release the earnest money.",
    useWhen="Buyer and seller agree to cancel a purchase contract, for example after an inspection or financing contingency, or by mutual agreement.",
    watchOuts=[
        "A unilateral termination notice under a contingency is different from a mutual cancellation. If you have a contractual right to terminate, exercise it in writing before the deadline, then use this form for the release.",
        "Escrow holders usually require both signatures, or a court order, to release disputed earnest money.",
        "If a licensee is involved, use the state-required release form where one exists (for example Colorado's Earnest Money Release).",
    ],
    disclaimer=RE_DISCLAIMER,
    roles=[("buyer", "Buyer"), ("seller", "Seller")],
    variables=[
        V("termination_date", "Date", "date", help="Date of termination."),
        V("buyer_name", "Buyer", "party", help="Buyer."),
        V("seller_name", "Seller", "party", help="Seller."),
        V("property_address", "Property", "address", help="Property address."),
        V("contract_date", "Contract date", "date", help="Effective date of the contract."),
        V("reason", "Reason", "select", default="mutual agreement", options=["mutual agreement", "inspection contingency", "financing contingency", "appraisal contingency", "title objection", "other contingency"], help="Basis for ending the contract."),
        V("escrow_holder", "Earnest money holder", "text", help="Who holds the deposit."),
        V("earnest_amount", "Earnest money amount", "money", help="Amount held."),
        V("disbursement", "Release earnest money", "select", default="all to buyer", options=["all to buyer", "all to seller", "split as stated"], help="Who receives the deposit."),
        V("buyer_share", "Amount to buyer", "money", False, help="If split."),
        V("seller_share", "Amount to seller", "money", False, help="If split."),
    ],
    sections=[
        S("Termination", "{{buyer_name}} (\"Buyer\") and {{seller_name}} (\"Seller\") terminate the purchase contract dated {{contract_date}} for {{property_address}} (the \"Contract\"), effective {{termination_date}}. Reason: {{reason}}."),
        S("Earnest money", "The parties instruct {{escrow_holder}} to release the earnest money of {{earnest_amount}}, minus any fees the Contract allows the holder to deduct, as follows: {{disbursement}}."),
        when("Split", "Buyer receives {{buyer_share}} and Seller receives {{seller_share}}.", "disbursement == 'split as stated'"),
        S("Mutual release", "Once the earnest money is released as instructed, Buyer and Seller release each other, and the escrow holder, from all claims and obligations under the Contract, except obligations the Contract says survive termination (for example repairing inspection damage) and any claim for fraud."),
        S("Property", "Buyer will return any keys, access devices and Seller documents, and Seller may market the property again immediately."),
        S("General", "This termination may be signed electronically and in counterparts, and the escrow holder may rely on it."),
        signatures([("buyer", "Buyer", "{{buyer_name}}"), ("seller", "Seller", "{{seller_name}}")]),
    ],
    sources=[SRC["crec"], SRC["trec"], SRC["esign"]],
))

# ------------------------------------------------------------------ Lead-based paint disclosure
LEAD_SALE = "Every purchaser of any interest in residential real property on which a residential dwelling was built prior to 1978 is notified that such property may present exposure to lead from lead-based paint that may place young children at risk of developing lead poisoning. Lead poisoning in young children may produce permanent neurological damage, including learning disabilities, reduced intelligence quotient, behavioral problems, and impaired memory. Lead poisoning also poses a particular risk to pregnant women. The seller of any interest in residential real property is required to provide the buyer with any information on lead-based paint hazards from risk assessments or inspections in the seller's possession and notify the buyer of any known lead-based paint hazards. A risk assessment or inspection for possible lead-based paint hazards is recommended prior to purchase."
LEAD_LEASE = "Housing built before 1978 may contain lead-based paint. Lead from paint, paint chips, and dust can pose health hazards if not managed properly. Lead exposure is especially harmful to young children and pregnant women. Before renting pre-1978 housing, lessors must disclose the presence of known lead-based paint and/or lead-based paint hazards in the dwelling. Lessees must also receive a federally approved pamphlet on lead poisoning prevention."

add(T(
    id="lead-based-paint-disclosure", title="Lead-Based Paint Disclosure (Sale or Lease)", category="real-estate",
    tags=["lead paint", "disclosure", "pre-1978", "federal", "lease", "sale"],
    summary="The federally required lead-based paint disclosure for selling or renting housing built before 1978, using the exact federal warning statements.",
    useWhen="Selling or leasing most residential housing built before 1978. It must be signed before the buyer or tenant is obligated under the contract or lease.",
    watchOuts=[
        "Timing matters: the disclosure, the records and the EPA pamphlet must be given before the buyer or tenant is bound. Giving them at closing or move-in is too late.",
        "Buyers get a 10-day opportunity to inspect for lead (or another agreed period) unless they waive it in writing. Tenants do not get this right.",
        "Exemptions include zero-bedroom units, housing for the elderly or disabled (unless a child under 6 lives or will live there), leases of 100 days or less, foreclosure sales and housing certified lead-free. See 40 CFR 745.101.",
        "Keep the signed form for at least three years. Penalties for violations can be substantial.",
        "Agents: if an agent represents the seller or landlord, the agent must also sign the agent certification. Add the agent as a signer or have the agent sign the certification on a copy.",
        "Some states and cities add their own lead rules, for example Massachusetts, Maryland, Rhode Island, New York City and Vermont.",
    ],
    disclaimer=RE_DISCLAIMER,
    roles=[("owner", "Seller or landlord"), ("recipient", "Buyer or tenant")],
    variables=[
        V("transaction", "Transaction", "select", default="sale", options=["sale", "lease"], help="The warning statement and buyer rights differ for sales and leases."),
        V("property_address", "Property address", "address", help="Housing built before 1978."),
        V("owner_name", "Seller or landlord name", "party", help="Seller or lessor."),
        V("recipient_name", "Buyer or tenant name", "party", help="Purchaser or lessee."),
        V("known_lbp", "Known lead-based paint or hazards", "select", default="no knowledge", options=["known lead-based paint and/or hazards are present", "no knowledge"], help="Seller or landlord's actual knowledge."),
        V("lbp_explanation", "Explanation of known lead-based paint or hazards", "longtext", False, help="Location, basis for the determination and condition of painted surfaces."),
        V("records", "Records or reports available", "select", default="no reports or records", options=["records and reports listed below have been provided", "no reports or records"], help="Lead inspections, risk assessments, abatement records."),
        V("records_list", "List of records provided", "longtext", False, help="Each document provided."),
        V("inspection_choice", "Buyer's 10-day inspection opportunity", "select", False, "received the opportunity", ["received the opportunity", "waived the opportunity"], help="Sales only."),
        V("agent_involved", "Is an agent involved?", "bool", False, "false", help="Agent certification is required when an agent represents the seller or landlord."),
        V("agent_name", "Agent name and brokerage", "text", False, help="Agent who signs the certification."),
    ],
    sections=[
        S("Property", "Property: {{property_address}}. This disclosure is for the {{transaction}} of housing built before 1978. Seller or landlord: {{owner_name}}. Buyer or tenant: {{recipient_name}}."),
        when("Lead warning statement (sales)", "**Lead Warning Statement**\n\n" + LEAD_SALE, "transaction == 'sale'"),
        when("Lead warning statement (leases)", "**Lead Warning Statement**\n\n" + LEAD_LEASE, "transaction == 'lease'"),
        S("Seller's or landlord's disclosure", "Presence of lead-based paint and/or lead-based paint hazards: {{known_lbp}}. Explanation (if known): {{lbp_explanation}}\n\nRecords and reports: {{records}}. {{records_list}}\n\nSeller or landlord initials: [[initial:owner]]"),
        S("Buyer's or tenant's acknowledgment", "\n".join([
            ack("recipient", "I have received copies of all information listed above."),
            ack("recipient", "I have received the pamphlet \"Protect Your Family From Lead in Your Home.\""),
        ])),
        when("Buyer's inspection opportunity (sales)", "Buyer has (check by initialing): {{inspection_choice}} to conduct a risk assessment or inspection for the presence of lead-based paint and/or lead-based paint hazards. Initials: [[initial:recipient]]", "transaction == 'sale'"),
        opt("Agent's acknowledgment", "Agent ({{agent_name}}) has informed the seller or landlord of their obligations under 42 U.S.C. 4852d and is aware of the agent's responsibility to ensure compliance. The agent signs this certification as an added signer or on a counterpart copy.", "agent_involved"),
        S("Certification of accuracy", "The following parties have reviewed the information above and certify, to the best of their knowledge, that the information they have provided is true and accurate."),
        signatures([("owner", "Seller or landlord", "{{owner_name}}"), ("recipient", "Buyer or tenant", "{{recipient_name}}")], ""),
    ],
    sources=[SRC["lead_cfr"], src("40 CFR 745.101: scope and exemptions (eCFR)", "https://www.ecfr.gov/current/title-40/chapter-I/subchapter-R/part-745/subpart-F/section-745.101"), src("40 CFR 745.110: opportunity to conduct an evaluation (eCFR)", "https://www.ecfr.gov/current/title-40/chapter-I/subchapter-R/part-745/subpart-F/section-745.110"), SRC["lead_epa"], SRC["lead_pamphlet"], SRC["lead_usc"]],
))
